let ph={running:true,principle:0,vendor:0,tool:0,modules:[true,true,true],ticks:0};
function phRender(){const vendors=['Grafana','Datadog','New Relic','Splunk'],tools=['Prometheus','Jaeger','Grafana','Kubernetes','Loki','Elasticsearch'];$('phrun').textContent=ph.running?'Pausar animação':'Iniciar animação';for(let i=0;i<3;i++)$('ph'+i).classList.toggle('ph-active',ph.principle===i);$('phdestination').textContent='Destino selecionado: '+vendors[ph.vendor];$('phcomposition').textContent=ph.modules.some(Boolean)?'Composição: '+['OTLP','Collector','Convenções'].filter((v,i)=>ph.modules[i]).join(' + '):'Escolha uma peça para começar.';$('phintegration').textContent='Explorando: '+tools[ph.tool];$('phinsight').textContent=['A instrumentação permanece. O destino pode mudar.','Adote as peças que resolvem o seu problema, no seu ritmo.','Combine OpenTelemetry com ferramentas do seu ecossistema.'][ph.principle];$('ph0').classList.toggle('ph-paused',!ph.running);$('ph2').classList.toggle('ph-paused',!ph.running);document.querySelectorAll('[data-ph-vendor]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.phVendor===ph.vendor)));document.querySelectorAll('[data-ph-tool]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.phTool===ph.tool)));document.querySelectorAll('[data-ph-module]').forEach(b=>b.setAttribute('aria-pressed',String(ph.modules[+b.dataset.phModule])));document.querySelectorAll('[data-ph-principle]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.phPrinciple===ph.principle)))}
$('phrun').onclick=()=>{ph.running=!ph.running;phRender()};document.querySelectorAll('[data-ph-vendor]').forEach(b=>b.onclick=()=>{ph.vendor=+b.dataset.phVendor;ph.principle=0;phRender()});document.querySelectorAll('[data-ph-tool]').forEach(b=>b.onclick=()=>{ph.tool=+b.dataset.phTool;ph.principle=2;phRender()});document.querySelectorAll('[data-ph-module]').forEach(b=>b.onclick=()=>{const i=+b.dataset.phModule;ph.modules[i]=!ph.modules[i];ph.principle=1;phRender()});document.querySelectorAll('[data-ph-principle]').forEach(b=>b.onclick=()=>{ph.principle=+b.dataset.phPrinciple;phRender()});
function phTick(){ph.ticks++;if(ph.ticks%5===0){if(ph.principle===0)ph.vendor=(ph.vendor+1)%4;else if(ph.principle===2)ph.tool=(ph.tool+1)%6;phRender()}}
let bn={selected:0,backend:0,running:true,filter:false,ticks:0};
function bnRender(){const examples=[['Portabilidade','Troque o destino sem reescrever a instrumentação. O Collector usa exporters e integrações compatíveis.'],['Padronização','service.name=checkout e deployment.environment.name=producao dão o mesmo significado aos dados entre equipes.'],['Correlação','O contexto da requisição pode ligar o trace ao log e a um exemplar de métrica.'],['Menos esforço','Instrumentação automática pode gerar telemetria de frameworks e bibliotecas suportados.'],['Ecossistema','Combine as ferramentas que você já utiliza: métricas, logs, traces, dashboards e alertas.'],['Controle do dado','Processe antes de exportar: filtre ruído, enriqueça atributos, amostre traces e escolha as rotas.']];$('bnheadline').textContent=examples[bn.selected][0];$('bnexample').textContent=examples[bn.selected][1];$('bnresource').textContent=bn.selected===1?'service.name: checkout':'service: checkout';$('bnprocess').textContent=bn.filter?'Filtro → Enriquecimento → Amostragem':'OTLP · exporters compatíveis';$('bnvolume').textContent=bn.filter?'Exemplo: 1.000 itens entram → 600 exportados':'Exemplo: 1.000 itens entram → 1.000 exportados';$('bnrun').textContent=bn.running?'Pausar animação':'Iniciar animação';$('bnfilter').textContent=bn.filter?'Remover filtro e amostragem':'Aplicar filtro e amostragem';$('bnfilter').setAttribute('aria-pressed',String(bn.filter));$('bnflow').classList.toggle('bn-paused',!bn.running);$('bnflow').classList.toggle('bn-filtered',bn.filter);document.querySelectorAll('[data-bn]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.bn===bn.selected)));document.querySelectorAll('[data-bn-backend]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.bnBackend===bn.backend)))}
document.querySelectorAll('[data-bn]').forEach(b=>b.onclick=()=>{bn.selected=+b.dataset.bn;bnRender()});document.querySelectorAll('[data-bn-backend]').forEach(b=>b.onclick=()=>{bn.backend=+b.dataset.bnBackend;bn.selected=0;bnRender()});$('bnrun').onclick=()=>{bn.running=!bn.running;bnRender()};$('bnfilter').onclick=()=>{bn.filter=!bn.filter;bn.selected=5;bnRender()};function bnTick(){bn.ticks++;if(bn.ticks%5===0){bn.backend=(bn.backend+1)%4;bnRender()}}
let ot={running:true,step:0,signal:0,process:false,ticks:0};
function otRender(){const signals=['Traces','Métricas','Logs','Profiles'],names=['Receivers: recebendo','Processors: processando','Exporters: enviando'],destinations=[['grafana','jaeger','other'],['grafana','prometheus','victoriametrics','other'],['grafana','loki','other'],['grafana','other']];$('otrunning').textContent=ot.running?'Pausar animação':'Iniciar animação';$('otphase').textContent=names[ot.step];$('otinputprotocol').textContent='OTLP / '+$('ottransport').value;$('otpayload').textContent='service.name: checkout\nsignal: '+signals[ot.signal].toLowerCase();$('otprocessorlabel').textContent=ot.process?'Filtrar ruído + adicionar atributos':'Filtro, transformação, enriquecimento';$('otprocess').textContent=ot.process?'Desativar filtro e enriquecimento':'Ativar filtro e enriquecimento';$('otprocess').setAttribute('aria-pressed',String(ot.process));$('otvolume').textContent=ot.process?'Exemplo: 1.000 recebidos → 700 enviados':'Exemplo: 1.000 recebidos → 1.000 enviados';$('otexplanation').textContent=['Traces mostram a jornada das requisições. Exemplo de destino: Jaeger.','Métricas mostram desempenho e estado. Exemplos: Prometheus e VictoriaMetrics.','Logs registram eventos e erros. Exemplo de destino: Loki.','Profiles ajudam a entender o consumo de recursos. A integração depende do suporte ao sinal.'][ot.signal];['otreceiver','otprocessor','otexporter'].forEach((id,i)=>$(id).classList.toggle('ot-active',i===ot.step));$('otdiagram').classList.toggle('ot-paused',!ot.running);$('otdiagram').classList.toggle('ot-filtering',ot.process);document.querySelectorAll('[data-ot-signal]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.otSignal===ot.signal)));document.querySelectorAll('[data-ot-backend]').forEach(b=>b.classList.toggle('ot-destination',destinations[ot.signal].includes(b.dataset.otBackend)))}
function otTick(){ot.ticks++;if(ot.ticks%2===0){ot.step=(ot.step+1)%3;otRender()}}
$('otrunning').onclick=()=>{ot.running=!ot.running;otRender()};$('otstep').onclick=()=>{ot.running=false;ot.step=(ot.step+1)%3;otRender()};$('otprocess').onclick=()=>{ot.process=!ot.process;otRender()};$('ottransport').onchange=otRender;document.querySelectorAll('[data-ot-signal]').forEach(b=>b.onclick=()=>{ot.signal=+b.dataset.otSignal;otRender()});
const lbTraces=[{id:'4f9a2c7b',color:'#b59aff',backend:0},{id:'7b21d8e4',color:'#66d9b0',backend:1},{id:'8c34f201',color:'#ffb34d',backend:0}];
const lbSpans=[{trace:0,id:'a001'},{trace:1,id:'b001'},{trace:0,id:'a002'},{trace:2,id:'c001'},{trace:1,id:'b002'},{trace:0,id:'a003'},{trace:2,id:'c002'}];
let lb={index:0,phase:0,ticks:0};
function lbTag(span,x,y,selected,zoom){const t=lbTraces[span.trace];return `<g class="lb-span-tag ${zoom?'lb-zoom':''}"><rect x="${x}" y="${y}" width="225" height="32" rx="5" fill="${selected?'#343142':'#182231'}" stroke="${t.color}" stroke-width="${selected?2.5:1}"/><circle cx="${x+13}" cy="${y+16}" r="4" fill="${t.color}"/><text x="${x+25}" y="${y+21}" fill="${t.color}" font-size="13">${t.id.slice(0,4)}…</text><text x="${x+113}" y="${y+21}" fill="#eef0f7" font-size="12">span …${span.id}</text></g>`}
function lbRender(){const active=lbSpans[lb.index],trace=lbTraces[active.trace],arrived=lb.phase>=4,sourceZoom=lb.phase===1,destZoom=lb.phase===4;const line=(d)=>`<path d="${d}" class="lb-route" marker-end="url(#lb-arrow)"/>`;let svg=`<svg viewBox="0 0 1000 540" role="img" aria-label="Spans do mesmo trace enviados ao mesmo Collector"><defs><marker id="lb-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 10 5 0 10z" fill="#91a3bb"/></marker></defs><rect x="15" y="65" width="265" height="365" rx="9" fill="#1c2b42" stroke="#7599c9" stroke-width="2"/><text class="lb-title" x="147" y="100" text-anchor="middle">Spans na origem</text><text class="lb-small" x="48" y="126">trace_id</text><text class="lb-small" x="162" y="126">span_id</text>`;
svg+=lbSpans.map((span,i)=>lbTag(span,35,142+i*39,i===lb.index,sourceZoom&&i===lb.index)).join('');
svg+=line('M280 260H425')+line('M605 245 C695 245,665 150,755 150')+line('M605 280 C695 280,665 365,755 365');
svg+=`<rect x="425" y="215" width="180" height="95" rx="8" fill="#34273e" stroke="#bd8ce3" stroke-width="2"/><text class="lb-title" x="515" y="250" text-anchor="middle">Load balancer</text><text class="lb-small" x="515" y="279" text-anchor="middle">routing_key: traceID</text>`;
for(let b=0;b<2;b++){const y=b===0?55:295;svg+=`<rect x="755" y="${y}" width="235" height="160" rx="8" fill="#193b32" stroke="${arrived&&b===trace.backend?trace.color:'#5da891'}" stroke-width="${arrived&&b===trace.backend?3:2}"/><text class="lb-title" x="872" y="${y+32}" text-anchor="middle">Collector ${b+1}</text>`;const examples=lbSpans.filter(sp=>lbTraces[sp.trace].backend===b).slice(0,2);svg+=examples.map((sp,j)=>lbTag(sp,760,y+50+j*40,false,false)).join('');if(arrived&&b===trace.backend)svg+=lbTag(active,760,y+90,true,destZoom);}
for(let i=0;i<lbTraces.length;i++){const t=lbTraces[i],out=t.backend===0?'M605 245 C695 245,665 150,755 150':'M605 280 C695 280,665 365,755 365';for(let j=0;j<2;j++)svg+=`<circle r="4" fill="${t.color}" class="lb-particle" style="offset-path:path('M280 260H425');animation-delay:${-i*.8-j*1.2}s"/><circle r="4" fill="${t.color}" class="lb-particle" style="offset-path:path('${out}');animation-delay:${-i*.8-j*1.2}s"/>`;}
const label=sourceZoom?'Lupa · span na origem':destZoom?'Lupa · mesmo span no destino':arrived?'Span entregue ao Collector '+(trace.backend+1):lb.phase>=2?'Roteando pelo trace_id':'Inspecionando o trace_id';
svg+=`<g class="lb-lens"><circle cx="333" cy="486" r="16" fill="none" stroke="${trace.color}" stroke-width="3"/><path d="M344 498l12 12" stroke="${trace.color}" stroke-width="4"/><text x="375" y="475" fill="${trace.color}" font-size="16">${label}</text><text x="375" y="501" fill="#f1edf7" font-size="18">trace ${trace.id}… · span …${active.id}</text></g></svg>`;$('lbaffinity').innerHTML=svg;}
function lbTick(){lb.ticks++;if(lb.ticks%2===0){lb.phase++;if(lb.phase>5){lb.phase=0;lb.index=(lb.index+1)%lbSpans.length}lbRender()}}
setInterval(()=>{if(document.hidden)return;const source=slides[current].source;if(source===28)lbTick();if(source===20&&ot.running)otTick();if(source===18&&bn.running)bnTick();if(source===17&&ph.running)phTick();if(source===16&&sig.running)sigTick();if(source===38&&q.running)qtick();if(source===41&&r.running)rtick();if(source===43&&m.running)mtick();if((source===47||source===48)&&k.running)ktick(1)},800);
